clc;
clear;
close all;

global x y

x = 2*pi:-0.1:-2*pi;
y = zeros(size(x));

neigiamas
teigiamas

plot(x, y, 'b-.+', 'LineWidth', 1.5); %[output:3bdfb482]
grid on; %[output:3bdfb482]

xlabel('x'); %[output:3bdfb482]
ylabel('y(x)'); %[output:3bdfb482]
title('Funkcijos grafikas'); %[output:3bdfb482]


